CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(120) UNIQUE NOT NULL,phone VARCHAR(20),password VARCHAR(255) NOT NULL,role ENUM('customer','provider','admin') NOT NULL DEFAULT 'customer',status ENUM('active','pending','blocked') NOT NULL DEFAULT 'active',address VARCHAR(255),vehicle VARCHAR(120),skills VARCHAR(255),avatar VARCHAR(255),online TINYINT DEFAULT 0,lat DOUBLE,lng DOUBLE,last_seen DATETIME,created DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60),icon VARCHAR(8),descr VARCHAR(200),base_price INT);
CREATE TABLE IF NOT EXISTS requests(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT,provider_id INT NULL,service_id INT,vehicle VARCHAR(120),note VARCHAR(255),lat DOUBLE,lng DOUBLE,address VARCHAR(255),status ENUM('pending','accepted','on_the_way','working','completed','cancelled') DEFAULT 'pending',price INT DEFAULT 0,rating TINYINT NULL,created DATETIME DEFAULT CURRENT_TIMESTAMP,updated DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(customer_id),INDEX(provider_id),INDEX(status));
CREATE TABLE IF NOT EXISTS messages(id INT AUTO_INCREMENT PRIMARY KEY,room VARCHAR(30),sender_id INT,body TEXT,created DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX(room));
